def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_prev = []
    moderate_prev = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if bid >= 50:
                    strong_prev.append(float(bid))
                elif bid >= 25:
                    moderate_prev.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    competitors = len(alive) + 1
    expected_need = competitors * WATER_REQ
    tightness = expected_need / float(supply) if supply > 0 else 10.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev
    david_like = max(moderate_prev) if moderate_prev else 38.0
    elite_like = max(strong_prev) if strong_prev else 55.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(elite_like + 2.0, DAILY_SALARY * 0.92)
    elif hp <= 4 or no_water_days >= 1:
        if tightness >= 1.9:
            bid = max(david_like + 2.5, 48.0)
        else:
            bid = max(32.0, second_prev * 0.9)
    else:
        if tightness >= 2.1:
            bid = max(david_like + 3.0, 44.0)
        elif tightness >= 1.8:
            bid = max(28.0, david_like + 1.0)
        elif tightness >= 1.5:
            bid = max(18.0, second_prev * 0.55)
        else:
            bid = 10.0

    if highest_prev >= 80 and hp > 4 and no_water_days == 0 and tightness < 2.0:
        bid = min(bid, 22.0)

    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid *= 0.9

    reserve = 0.0
    if hp > 3:
        reserve = DAILY_SALARY * 0.35
    cap = max(0.0, budget - reserve)
    if hp <= 3 or no_water_days >= 1:
        cap = budget

    bid = min(bid, cap if cap > 0 else budget)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    alive_opp = [o for o in opponents_status.values() if o['alive']]
    prev_bids = []
    for opp in alive_opp:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])
    if prev_bids:
        median = sorted(prev_bids)[len(prev_bids)//2]
        target = median + 2.0
    else:
        target = DAILY_SALARY * 0.5
    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 2:
        target = max(target, DAILY_SALARY * 0.75)
    return min(my_status['budget'], max(0.01, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        if highest_prev > 70:
            return min(my_status['budget'], 45.0)
        return min(my_status['budget'], highest_prev + 5.0)

    return min(my_status['budget'], 40.0)
